const CLASS_NAME_OPEN = 'sidebar-search-open'
const CLASS_NAME_ICON_SEARCH = 'bi-search'
const CLASS_NAME_ICON_CLOSE = 'bi-x-lg'
const CLASS_NAME_HEADER = 'nav-header'
const CLASS_NAME_SEARCH_RESULTS = 'sidebar-search-results'
const CLASS_NAME_LIST_GROUP = 'list-group'

const SELECTOR_DATA_WIDGET = '[data-widget="sidebar-search"]'
const SELECTOR_SIDEBAR = '.app-sidebar .sidebar-menu'
const SELECTOR_NAV_LINK = '.nav-link'
const SELECTOR_NAV_TREEVIEW = '.nav-treeview'
const SELECTOR_SEARCH_INPUT = `${SELECTOR_DATA_WIDGET} .form-control`
const SELECTOR_SEARCH_BUTTON = `${SELECTOR_DATA_WIDGET} .btn`
const SELECTOR_SEARCH_ICON = `${SELECTOR_SEARCH_BUTTON} i`
const SELECTOR_SEARCH_LIST_GROUP = `.${CLASS_NAME_LIST_GROUP}`
const SELECTOR_SEARCH_RESULTS = `.${CLASS_NAME_SEARCH_RESULTS}`
const SELECTOR_SEARCH_RESULTS_GROUP = `${SELECTOR_SEARCH_RESULTS} .${CLASS_NAME_LIST_GROUP}`

type Configs = {
  arrowSign: string;
  minLength: number;
  maxResults: number;
  highlightName: boolean;
  highlightPath: boolean;
  highlightClass: string;
  notFoundText: string;
}

type ItemObject = {
  name: string;
  link: string;
  path: string;
}

const Defaults: Configs = {
  arrowSign: '->',
  minLength: 3,
  maxResults: 7,
  highlightName: true,
  highlightPath: false,
  highlightClass: 'text-light',
  notFoundText: 'No element found!'
}

const SearchItems: ItemObject[] = []

/**
 * Class Definition
 * ====================================================
 */

class SidebarSearch {
  element: HTMLElement
  options: Configs
  items: any[] = []
  constructor(_element: HTMLElement, _options: Configs) {
    this.element = _element
    this.options = { ...Defaults, ..._options }
    this.items = []
  }

  // Public
  init() {
    if (document.querySelectorAll(SELECTOR_DATA_WIDGET).length === 0) {
      return
    }

    if (document.querySelectorAll(`${SELECTOR_DATA_WIDGET} + ${SELECTOR_SEARCH_RESULTS}`).length === 0) {
      document.querySelector(SELECTOR_DATA_WIDGET)?.insertAdjacentHTML('afterend', `<div class="${CLASS_NAME_SEARCH_RESULTS}"></div>`)
    }

    if (document.querySelectorAll(`${SELECTOR_SEARCH_RESULTS} ${SELECTOR_SEARCH_LIST_GROUP}`).length === 0) {
      // append
      document.querySelector(SELECTOR_SEARCH_RESULTS)?.insertAdjacentHTML('beforeend', `<div class="${CLASS_NAME_LIST_GROUP}"></div>`)
    }

    this._addNotFound()

    const childs = document.querySelector(SELECTOR_SIDEBAR)?.children
    if (childs) {
      Array.from(childs).forEach(child => {
        this._parseItem(child)
      })
    }
  }

  search() {
    const searchElement = document.querySelector(SELECTOR_SEARCH_INPUT)
    const searchValue: string = (searchElement) ? ((searchElement as HTMLInputElement).value.toLowerCase()) : ''
    const searchResultGroup = document.querySelector(SELECTOR_SEARCH_RESULTS_GROUP)!
    if (searchValue.length < this.options.minLength) {
      searchResultGroup.innerHTML = ''
      this._addNotFound()
      this.close()
      return
    }

    const searchResults = SearchItems.filter(item => (item.name).toLowerCase().includes(searchValue))
    const endResults = searchResults.slice(0, this.options.maxResults)
    searchResultGroup.innerHTML = ''

    if (endResults.length === 0) {
      this._addNotFound()
    } else {
      endResults.forEach(result => {
        // append
        searchResultGroup.insertAdjacentHTML('beforeend', this._renderItem(escape(result.name), encodeURI(result.link), [result.path]))
      })
    }

    this.open()
  }

  open() {
    document.querySelector(SELECTOR_DATA_WIDGET)?.parentElement?.classList.add(CLASS_NAME_OPEN)
    document.querySelector(SELECTOR_SEARCH_ICON)?.classList.remove(CLASS_NAME_ICON_SEARCH)
    document.querySelector(SELECTOR_SEARCH_ICON)?.classList.add(CLASS_NAME_ICON_CLOSE)
  }

  close() {
    document.querySelector(SELECTOR_DATA_WIDGET)?.parentElement?.classList.remove(CLASS_NAME_OPEN)
    document.querySelector(SELECTOR_SEARCH_ICON)?.classList.remove(CLASS_NAME_ICON_CLOSE)
    document.querySelector(SELECTOR_SEARCH_ICON)?.classList.add(CLASS_NAME_ICON_SEARCH)
  }

  toggle() {
    if (document.querySelector(SELECTOR_DATA_WIDGET)?.parentElement?.classList.contains(CLASS_NAME_OPEN)) {
      this.close()
    } else {
      this.open()
    }
  }

  // Private

  _parseItem(item: Element, path: string[] = []) {
    if (item.classList.contains(CLASS_NAME_HEADER)) {
      return
    }

    const itemObject: ItemObject = {
      name: '',
      link: '',
      path: ''
    }
    const navLink = (item.cloneNode(true) as HTMLElement).querySelector(`${SELECTOR_NAV_LINK}`)
    const navTreeview = (item.cloneNode(true) as HTMLElement).querySelector(`${SELECTOR_NAV_TREEVIEW}`)

    const link = (navLink?.getAttribute('href')) ?? ''
    const name = navLink?.querySelector('p')?.textContent ?? ''

    itemObject.name = this._trimText(name)
    itemObject.link = link
    itemObject.path = path.join(` ${this.options.arrowSign} `)

    if (navTreeview === null) {
      SearchItems.push(itemObject)
    } else {
      const newPath = itemObject.path.concat(itemObject.name)
      const childs = navTreeview.children
      // navTreeview.children().each((i, child) => {
      //   this._parseItem(child, newPath)
      // })
      if (childs) {
        Array.from(childs).forEach(child => {
          this._parseItem(child, [newPath])
        })
      }
    }
  }

  //
  _trimText(text: string) {
    return (text.replace(/(\r\n|\n|\r)/gm, ' ')).trim()
  }

  _renderItem(name: string, link: string, path: string[]) {
    let varpath: string = path.join(` ${this.options.arrowSign} `)
    let varname: string = unescape(name)
    const varlink: string = decodeURI(link)

    if (this.options.highlightName || this.options.highlightPath) {
      const searchElement = document.querySelector(SELECTOR_SEARCH_INPUT)
      const searchValue: string = (searchElement) ? ((searchElement as HTMLInputElement).value.toLowerCase()) : ''
      const regExp = new RegExp(searchValue, 'gi')

      if (this.options.highlightName) {
        varname = varname.replace(
          regExp,
          str => {
            return `<strong class="${this.options.highlightClass}">${str}</strong>`
          }
        )
      }

      if (this.options.highlightPath) {
        varpath = varpath.replace(
          regExp,
          str => {
            return `<strong class="${this.options.highlightClass}">${str}</strong>`
          }
        )
      }
    }

    const groupItemElement = `<a class="list-group-item" href="${decodeURIComponent(varlink)}"><div class="search-title">${varname}</div><div class="search-path">${varpath}</div></a>`

    // const groupItemElement = $('<a/>', {
    //   href: decodeURIComponent(varlink),
    //   class: 'list-group-item'
    // })
    // const searchTitleElement = $('<div/>', {
    //   class: 'search-title'
    // }).html(varname)
    // const searchPathElement = $('<div/>', {
    //   class: 'search-path'
    // }).html(varpath)
    // groupItemElement.append(searchTitleElement).append(searchPathElement)

    return groupItemElement
  }

  _addNotFound() {
    // append
    document.querySelector(SELECTOR_SEARCH_RESULTS_GROUP)?.insertAdjacentHTML('beforeend', this._renderItem(this.options.notFoundText, '#', []))
  }

  // Static

  // static _interface(config: Configs | keyof SidebarSearch) {
  //   const element = document.querySelector(SELECTOR_DATA_WIDGET)
  //   if (element) {
  //     const options = (typeof config === 'object') ? { ...Defaults, ...config } : Defaults
  //     const plugin = new SidebarSearch((element as HTMLElement), options)
  //     if (typeof config === 'string') {
  //       // eslint-disable-next-line @typescript-eslint/ban-ts-comment
  //       // @ts-expect-error
  //       plugin[config]()
  //     } else {
  //       plugin.init()
  //     }
  //   }
  // }
}
