onDOMContentLoaded(() => {
  const sidebarSearchInput = document.querySelector(SELECTOR_SEARCH_INPUT)
  const sidebarSearchElemnt = document?.querySelector(SELECTOR_DATA_WIDGET) as HTMLElement | undefined
  const sidebarSearch = (sidebarSearchElemnt) ? new SidebarSearch(sidebarSearchElemnt, Defaults) : null
  sidebarSearch?.init()
  const searchButton = document.querySelector(SELECTOR_SEARCH_BUTTON)
  const searchResultGroup = document.querySelector(SELECTOR_SEARCH_RESULTS_GROUP)
  const searchResultGroupChilds = searchResultGroup?.children

  searchButton?.addEventListener('click', event => {
    event.preventDefault()
    sidebarSearch?.toggle()
  })

  sidebarSearchInput?.addEventListener('keyup', e => {
    const event = e as KeyboardEvent
    sidebarSearch?.toggle()
    if (event.key === 'ArrowUp') {
      event.preventDefault()
      if (searchResultGroupChilds) {
        const lastchild = searchResultGroupChilds.item(searchResultGroupChilds.length - 1) as HTMLElement
        lastchild.focus()
      }
    }

    if (event.key === 'ArrowDown') {
      event.preventDefault()
      if (searchResultGroupChilds) {
        const firtchild = searchResultGroupChilds.item(0) as HTMLElement
        firtchild.focus()
      }
    }

    setTimeout(() => {
      sidebarSearch?.search()
    }, 100)
  })

  searchResultGroup?.addEventListener('keydown', e => {
    const event = e as KeyboardEvent
    const focused = document.querySelector(':focus')
    if (event.key === 'ArrowUp') {
      event.preventDefault()
      if (focused) {
        if (focused?.matches(':first-child')) {
          const lastChild = focused?.parentNode?.lastChild as HTMLElement
          if (lastChild) {
            lastChild.focus()
          }
        } else {
          const previousSibling = focused.previousSibling as HTMLElement
          if (previousSibling) {
            previousSibling.focus()
          }
        }
      }
    }

    if (event.key === 'ArrowDown') {
      event.preventDefault()
      if (focused) {
        if (focused?.matches(':last-child')) {
          // $focused.siblings().first().focus()
          const firstChild = focused?.parentNode?.firstChild as HTMLElement
          if (firstChild) {
            firstChild.focus()
          }
        } else {
          // $focused.next().focus()
          const nextSibling = focused.nextSibling as HTMLElement
          if (nextSibling) {
            nextSibling.focus()
          }
        }
      }
    }
  })
})

export default SidebarSearch
